    public partial class TeachingHourResultAll : ControlBase
    {
        public const string PERMISSION_VIEW = "frmBangTinhGioDayGiangVien_ALL_View";

        // Ngưỡng (cap) cho các hoạt động - Khoa <> 'DTLX'
        public const decimal THRESHOLD_HOCTAP_BOIDUONG = 26m;
        public const decimal THRESHOLD_NCKH = 78m;
        public const decimal THRESHOLD_HOATDONG_KHAC = 52m;

        // Khoa = 'DTLX'
        public const decimal THRESHOLD_HOATDONG_KHAC_DTLX = 26m;

        private const string SESSION_DATA_KEY = "TeachingHourResultAll_Data";

        private string _lastScienceName = null;

        #region Properties

        private DataTable CachedData
        {
            get { return Session[SESSION_DATA_KEY] as DataTable; }
            set { Session[SESSION_DATA_KEY] = value; }
        }

        #endregion

        #region Page lifecycle

        protected void Page_Load(object sender, EventArgs e)
        {
            uTeacher.SearchClick += new Sims.UTeacher2.SearchDelegate(uTeacher_SearchClick);

            if (!IsPostBack)
            {
                if (User == null)
                {
                    MsgBox.ShowWarning("Chức năng này chỉ dành cho nhà quản lý, vui lòng đăng nhập!");
                    Response.Redirect("~/");
                    return;
                }

                uTeacher.ShowSearchButton = false;
                uYearSemester.LoadData();
                LoadTeacherType();
                chkNOTlaiXe.Checked = true;
            }
        }

        #endregion

        #region Load reference

        private void LoadTeacherType()
        {
            SIM_TeacherType obj = new SIM_TeacherType();
            DataTable dtb = obj.GetAll();
            if (dtb != null)
            {
                WebGlobal.InitDropDownList(ddlTeacherTypeID, dtb,
                    SIM_TeacherType.C_TeacherTypeID,
                    SIM_TeacherType.C_TeacherTypeName,
                    "--Chọn--");
            }
        }

        #endregion

        #region Search / Load data

        private void uTeacher_SearchClick(object scienceID, object subjectGroupID, object teacherID)
        {
            btnSearch_Click(null, null);
        }

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            if (!IsValidData())
                return;

            ReadData();
        }

        private bool IsValidData()
        {
            if (uYearSemester.YearID == null)
            {
                MsgBox.ShowWarning("Bạn phải chọn niên học!");
                return false;
            }

            if (!chkFullYear.Checked && uYearSemester.Semester == null)
            {
                MsgBox.ShowWarning("Bạn phải chọn học kỳ (hoặc chọn Cả năm)!");
                return false;
            }

            return true;
        }

        private object GetTeacherTypeID()
        {
            if (ddlTeacherTypeID.SelectedValue == null || ddlTeacherTypeID.SelectedValue == "")
                return null;
            return Convert.ToInt32(ddlTeacherTypeID.SelectedValue);
        }

        private object NormalizeFilterValue(object value)
        {
            if (value == null || value == DBNull.Value)
                return null;
            if (value.ToString().Trim() == "")
                return null;
            return value;
        }

        private void ReadData()
        {
            SIM_Branch obj = new SIM_Branch();
            DataTable dtbData = null;

            object scienceID = NormalizeFilterValue(uTeacher.ScienceID);
            object subjectGroupID = NormalizeFilterValue(uTeacher.SubjectGroupID);
            object teacherID = NormalizeFilterValue(uTeacher.TeacherID);
            object teacherTypeID = GetTeacherTypeID();
            object yearID = uYearSemester.YearID;
            bool bolNotLaiXe = chkNOTlaiXe.Checked;

            if (chkFullYear.Checked)
            {
                // Load học kỳ 1
                DataTable dtbHK1 = obj.GetDataTable(
                    "SIM_Schedule_TK_KetQuaThucHienNhaGiao",
                    "@ScienceIDOfTeacher", scienceID,
                    "@SubjectGroupIDOfTeacher", subjectGroupID,
                    "@TeacherID", teacherID,
                    "@YearID", yearID,
                    "@TeacherTypeID", teacherTypeID,
                    "@chkNOTlaiXe", bolNotLaiXe,
                    "@Semester", "1"
                );

                // Load học kỳ 2
                DataTable dtbHK2 = obj.GetDataTable(
                    "SIM_Schedule_TK_KetQuaThucHienNhaGiao",
                    "@ScienceIDOfTeacher", scienceID,
                    "@SubjectGroupIDOfTeacher", subjectGroupID,
                    "@TeacherID", teacherID,
                    "@YearID", yearID,
                    "@TeacherTypeID", teacherTypeID,
                    "@chkNOTlaiXe", bolNotLaiXe,
                    "@Semester", "2"
                );

                dtbData = MergeAndSumByTeacher(dtbHK1, dtbHK2);
            }
            else
            {
                dtbData = obj.GetDataTable(
                    "SIM_Schedule_TK_KetQuaThucHienNhaGiao",
                    "@ScienceIDOfTeacher", scienceID,
                    "@SubjectGroupIDOfTeacher", subjectGroupID,
                    "@TeacherID", teacherID,
                    "@YearID", yearID,
                    "@TeacherTypeID", teacherTypeID,
                    "@chkNOTlaiXe", bolNotLaiXe,
                    "@Semester", uYearSemester.Semester
                );
            }

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                CachedData = null;
                BindEmpty("Không có dữ liệu!");
                return;
            }

            AddComputedColumns(dtbData);

            if (dtbData.Columns.Contains("ScienceName"))
                dtbData.DefaultView.Sort = "ScienceName ASC, TeacherLastName ASC, TeacherFirstName ASC";

            if (chkHasTeachingHours.Checked)
                dtbData.DefaultView.RowFilter = "TongLTTH > 0";
            else
                dtbData.DefaultView.RowFilter = "";

            CachedData = dtbData;
            BindGrid(dtbData.DefaultView.ToTable());
        }

        private void BindEmpty(string message)
        {
            rptList.DataSource = null;
            rptList.DataBind();
            ltrEmpty.Visible = true;
            ltrEmpty.Text = String.Format("<div class='alert alert-warning'>{0}</div>", message);
            udpMain.Update();
        }

        private void BindGrid(DataTable dtb)
        {
            ltrEmpty.Visible = false;
            ltrEmpty.Text = "";
            _lastScienceName = null;

            if (dtb == null || dtb.Rows.Count == 0)
            {
                BindEmpty("Không có dữ liệu!");
                return;
            }

            rptList.DataSource = dtb;
            rptList.DataBind();
            udpMain.Update();
        }

        #endregion

        #region Computed columns (y như WinForms)

        private void AddComputedColumns(DataTable dtbData)
        {
            string[] requiredCols = {
                "StandardQuantity_DinhMucGiangDay",
                "TeacherTypeID",
                "TotalFinal_W34_HocTapBoiDuong",
                "TotalFinal_W35_HoatDongKhac",
                "ResearchNow_NCKH",
                "TongLTTH",
                "GioQuyDoi_CoiThi",
                "GioQuyDoi_ChamThi",
                "SoGioSoanDe"
            };

            foreach (string col in requiredCols)
            {
                if (!dtbData.Columns.Contains(col))
                    return;
            }

            if (!dtbData.Columns.Contains("TongCoiThiChamThiSoanDe"))
            {
                dtbData.Columns.Add("TongCoiThiChamThiSoanDe", typeof(decimal),
                    "ISNULL(GioQuyDoi_CoiThi, 0) + ISNULL(GioQuyDoi_ChamThi, 0) + ISNULL(SoGioSoanDe, 0)");
            }

            if (!dtbData.Columns.Contains("TongSoGioGiangDayHoatDong"))
            {
                dtbData.Columns.Add("TongSoGioGiangDayHoatDong", typeof(decimal),
                    "ISNULL(TongCoiThiChamThiSoanDe, 0) + ISNULL(TotalFinal_W34_HocTapBoiDuong, 0) + ISNULL(TotalFinal_W35_HoatDongKhac, 0) + ISNULL(ResearchNow_NCKH, 0) + ISNULL(TongLTTH, 0)");
            }

            // TeacherTypeID = 5 (GV khoa): ĐM GD + 26 + 78 + 52
            // TeacherTypeID = 8 (GV khoa trung tâm): ĐM GD + 78
            if (!dtbData.Columns.Contains("DinhMucTong2024"))
            {
                string dinhMucExpr = String.Format(
                    "IIF(ISNULL(TeacherTypeID, 0) = 5, ISNULL(RealStandardQuantity_DinhMucGiangDayNamHoc, 0) + {0} + {1} + {2}, IIF(ISNULL(TeacherTypeID, 0) = 8, ISNULL(RealStandardQuantity_DinhMucGiangDayNamHoc, 0) + {1}, 0))",
                    THRESHOLD_HOCTAP_BOIDUONG,
                    THRESHOLD_NCKH,
                    THRESHOLD_HOATDONG_KHAC);

                dtbData.Columns.Add("DinhMucTong2024", typeof(decimal), dinhMucExpr);
            }

            if (!dtbData.Columns.Contains("VuotToiThieu"))
            {
                dtbData.Columns.Add("VuotToiThieu", typeof(decimal),
                    "ISNULL(TongSoGioGiangDayHoatDong, 0) - ISNULL(DinhMucTong2024, 0)");
            }
        }

        #endregion

        #region Merge cả năm (y như WinForms)

        private DataTable MergeAndSumByTeacher(DataTable dtbHK1, DataTable dtbHK2)
        {
            if (dtbHK1 == null || dtbHK1.Rows.Count == 0)
                return dtbHK2;

            if (dtbHK2 == null || dtbHK2.Rows.Count == 0)
                return dtbHK1;

            DataTable dtbResult = dtbHK1.Clone();
            List<string> listNumericCols = new List<string>();

            foreach (DataColumn col in dtbResult.Columns)
            {
                if (col.DataType == typeof(decimal)
                    || col.DataType == typeof(double)
                    || col.DataType == typeof(int)
                    || col.DataType == typeof(long)
                    || col.DataType == typeof(float))
                {
                    if (col.ColumnName != "TeacherID"
                        && col.ColumnName != "TeacherTypeID")
                        listNumericCols.Add(col.ColumnName);
                }
            }

            Dictionary<string, DataRow> dictData = new Dictionary<string, DataRow>();

            foreach (DataRow row in dtbHK1.Rows)
            {
                string strTeacherID = row["TeacherID"].ToString();
                DataRow newRow = dtbResult.NewRow();
                foreach (DataColumn col in dtbResult.Columns)
                    newRow[col.ColumnName] = row[col.ColumnName];
                dictData[strTeacherID] = newRow;
            }

            foreach (DataRow row in dtbHK2.Rows)
            {
                string strTeacherID = row["TeacherID"].ToString();

                if (dictData.ContainsKey(strTeacherID))
                {
                    DataRow existingRow = dictData[strTeacherID];
                    foreach (string strCol in listNumericCols)
                    {
                        decimal val1 = 0;
                        decimal val2 = 0;

                        if (existingRow[strCol] != DBNull.Value)
                            val1 = Convert.ToDecimal(existingRow[strCol]);

                        if (row[strCol] != DBNull.Value)
                            val2 = Convert.ToDecimal(row[strCol]);

                        existingRow[strCol] = val1 + val2;
                    }
                }
                else
                {
                    DataRow newRow = dtbResult.NewRow();
                    foreach (DataColumn col in dtbResult.Columns)
                        newRow[col.ColumnName] = row[col.ColumnName];
                    dictData[strTeacherID] = newRow;
                }
            }

            foreach (DataRow row in dictData.Values)
            {
                CapCombinedValues(row);
                dtbResult.Rows.Add(row);
            }

            return dtbResult;
        }

        private void CapCombinedValues(DataRow row)
        {
            string strScienceID = "";
            if (row.Table.Columns.Contains("ScienceID")
                && row["ScienceID"] != DBNull.Value)
            {
                strScienceID = row["ScienceID"].ToString();
            }

            bool bolIsDTLX = (strScienceID == "DTLX");

            CapColumn(row, "TotalFinal_W34_HocTapBoiDuong", THRESHOLD_HOCTAP_BOIDUONG);

            CapColumn(row, "TotalFinal_W35_HoatDongKhac",
                bolIsDTLX ? THRESHOLD_HOATDONG_KHAC_DTLX : THRESHOLD_HOATDONG_KHAC);

            if (!bolIsDTLX)
                CapColumn(row, "ResearchNow_NCKH", THRESHOLD_NCKH);
        }

        private void CapColumn(DataRow row, string strColName, decimal dMax)
        {
            if (!row.Table.Columns.Contains(strColName))
                return;

            object objVal = row[strColName];
            if (objVal == DBNull.Value || objVal == null)
                return;

            decimal dVal;
            if (!decimal.TryParse(objVal.ToString(), out dVal))
                return;

            if (dVal > dMax)
                row[strColName] = dMax;
        }

        #endregion

        #region Events UI

        protected void chkFullYear_CheckedChanged(object sender, EventArgs e)
        {
            // Khi chọn "Cả năm" thì disable chọn học kỳ (giữ năm để lọc)
            uYearSemester.SemesterEnabled = !chkFullYear.Checked;
        }

        protected void chkHasTeachingHours_CheckedChanged(object sender, EventArgs e)
        {
            DataTable dtbData = CachedData;
            if (dtbData == null || dtbData.Rows.Count == 0)
                return;

            if (chkHasTeachingHours.Checked)
                dtbData.DefaultView.RowFilter = "TongLTTH > 0";
            else
                dtbData.DefaultView.RowFilter = "";

            BindGrid(dtbData.DefaultView.ToTable());
        }

        protected void rptList_ItemDataBound(object sender, RepeaterItemEventArgs e)
        {
            if (e.Item.ItemType != ListItemType.Item && e.Item.ItemType != ListItemType.AlternatingItem)
                return;

            DataRowView drv = e.Item.DataItem as DataRowView;
            if (drv == null)
                return;

            Literal ltrGroup = e.Item.FindControl("ltrGroup") as Literal;
            if (ltrGroup == null)
                return;

            string scienceName = "";
            if (drv.Row.Table.Columns.Contains("ScienceName") && drv["ScienceName"] != DBNull.Value)
                scienceName = drv["ScienceName"].ToString();

            if (string.IsNullOrEmpty(scienceName))
                scienceName = "(Chưa có đơn vị)";

            if (_lastScienceName != scienceName)
            {
                _lastScienceName = scienceName;
                ltrGroup.Text = String.Format(
                    "<tr style='background:#92d050;color:#004600;font-weight:bold'><td colspan='19'>{0}</td></tr>",
                    Server.HtmlEncode(scienceName));
            }
        }

        protected string FormatNumber(object value)
        {
            if (value == null || value == DBNull.Value)
                return "";

            decimal d;
            if (decimal.TryParse(value.ToString(), out d))
                return String.Format("{0:#,##0.00}", d);

            return value.ToString();
        }

        #endregion

        #region Export Excel

        protected void btnExportExcel_Click(object sender, EventArgs e)
        {
            DataTable dtbData = CachedData;
            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                MsgBox.ShowWarning("Không có dữ liệu để xuất!");
                return;
            }

            DataView dv = dtbData.DefaultView;
            DataTable dtbExport = dv.ToTable();

            StringBuilder sb = new StringBuilder();
            sb.Append("<html><head><meta http-equiv='Content-Type' content='text/html; charset=utf-8' /></head><body>");
            sb.Append("<table border='1'>");
            sb.Append("<tr>");
            sb.Append("<th>TT</th>");
            sb.Append("<th>Mã GV</th><th>Họ đệm</th><th>Tên</th><th>Họ tên</th><th>Đơn vị</th>");
            sb.Append("<th>Giờ QĐ coi thi</th><th>Giờ QĐ chấm thi</th><th>Giờ soạn đề</th><th>Tổng CT+CT+SD</th>");
            sb.Append("<th>Định mức GD</th><th>Định mức giảm KN</th><th>Định mức GD năm học</th>");
            sb.Append("<th>HT, bồi dưỡng</th><th>HĐ khác</th><th>NCKH</th><th>Tổng LT+TH</th>");
            sb.Append("<th>Tổng số giờ giảng dạy, hoạt động</th><th>Tổng định mức giờ chuẩn</th><th>Vượt tối thiểu</th>");
            sb.Append("</tr>");

            int i = 1;
            foreach (DataRow drw in dtbExport.Rows)
            {
                sb.Append("<tr>");
                sb.AppendFormat("<td>{0}</td>", i++);
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "TeacherID"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "TeacherFirstName"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "TeacherLastName"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "TeacherName"));
                sb.AppendFormat("<td>{0}</td>", HtmlVal(drw, "ScienceName"));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "GioQuyDoi_CoiThi")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "GioQuyDoi_ChamThi")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "SoGioSoanDe")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "TongCoiThiChamThiSoanDe")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "StandardQuantity_DinhMucGiangDay")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "RatioPositionValue_DinhMucGiamKiemNhiem")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "RealStandardQuantity_DinhMucGiangDayNamHoc")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "TotalFinal_W34_HocTapBoiDuong")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "TotalFinal_W35_HoatDongKhac")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "ResearchNow_NCKH")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "TongLTTH")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "TongSoGioGiangDayHoatDong")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "DinhMucTong2024")));
                sb.AppendFormat("<td>{0}</td>", FormatNumber(GetVal(drw, "VuotToiThieu")));
                sb.Append("</tr>");
            }

            sb.Append("</table></body></html>");

            string fileName = String.Format("BangTinhGioDayGV_{0}.xls", DateTime.Now.ToString("yyyyMMdd_HHmmss"));
            Response.Clear();
            Response.Buffer = true;
            Response.ContentType = "application/vnd.ms-excel";
            Response.AddHeader("content-disposition", "attachment;filename=" + fileName);
            Response.Charset = "utf-8";
            Response.ContentEncoding = Encoding.UTF8;
            Response.Write(sb.ToString());
            Response.End();
        }

        private object GetVal(DataRow drw, string col)
        {
            if (drw.Table.Columns.Contains(col))
                return drw[col];
            return DBNull.Value;
        }

        private string HtmlVal(DataRow drw, string col)
        {
            object val = GetVal(drw, col);
            if (val == null || val == DBNull.Value)
                return "";
            return Server.HtmlEncode(val.ToString());
        }

        #endregion
